-- Data backfill: give every EXISTING clinic its own copy of the starter
-- anamneses. New clinics get them from the sign-up hook; clinics created before
-- the anamnese feature have none, so this seeds them — once, at deploy time
-- (the migrator applies each migration exactly once). Only clinics that have NO
-- anamnese yet are touched, so a re-run or a clinic already seeded by the hook is
-- left untouched.
INSERT INTO "anamnesis" ("clinic_id", "coach_id", "name", "description", "objective", "modality", "sections")
SELECT c."id", c."owner_user_id", t.name, t.description, t.objective, t.modality, t.sections
FROM "clinic" c
CROSS JOIN (VALUES
